<?php

declare(strict_types=1);

require __DIR__.'/_init.php';$admin=require_admin();$id=filter_var($_GET['id']??$_POST['product_id']??null,FILTER_VALIDATE_INT)?:null;$tab=(string)($_GET['tab']??'details');if(!in_array($tab,['details','variants','images'],true))$tab='details';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        admin_post_guard();$action=(string)($_POST['action']??'save_product');
        if($action==='save_product'){$id=admin_service()->saveProduct($_POST,$id);flash('success','Product saved.');$tab='details';}
        elseif($action==='save_variant'){if(!$id)throw new DomainException('Save the product first.');admin_service()->saveVariant($_POST,filter_var($_POST['variant_id']??null,FILTER_VALIDATE_INT)?:null);flash('success','Variant saved.');$tab='variants';}
        elseif($action==='delete_variant'){if(!admin_repository()->deleteVariantIfSafe((int)($_POST['variant_id']??0)))throw new DomainException('This variant is referenced by a cart or order. Disable it instead.');admin_repository()->audit((int)$admin['id'],'variant.delete','variant',(int)$_POST['variant_id'],'Deleted unreferenced variant.');flash('success','Variant deleted.');$tab='variants';}
        elseif($action==='upload_images'){if(!$id)throw new DomainException('Save the product first.');$count=admin_service()->uploadImages($id,$_FILES['images']??[],(string)($_POST['alt_text']??''),(string)($_POST['color_slug']??''));flash('success',$count.' image'.($count===1?'':'s').' uploaded.');$tab='images';}
        elseif($action==='update_image'){admin_service()->updateImage((int)($_POST['image_id']??0),$_POST);flash('success','Image updated.');$tab='images';}
        elseif($action==='delete_image'){admin_service()->deleteImage((int)($_POST['image_id']??0));flash('success','Image removed.');$tab='images';}
        else throw new DomainException('Invalid product action.');
    }catch(Throwable$exception){admin_flash_exception($exception);}admin_redirect('product-edit.php'.($id?'?id='.$id.'&tab='.$tab:''));
}
$product=$id?admin_repository()->product((int)$id):null;if($id&&!$product){http_response_code(404);exit('Product not found.');}$categories=admin_repository()->categories();$collections=admin_repository()->collections();
$editVariantId=filter_var($_GET['variant']??null,FILTER_VALIDATE_INT)?:null;$editVariant=null;if($editVariantId&&$product)foreach($product['variants']as$row)if((int)$row['id']===$editVariantId)$editVariant=$row;
$adminTitle=$product?'Edit '.$product['name']:'New product';$adminPage='products';$adminSection='Store';$adminActions='<div class="page-actions"><a class="button button--quiet" href="'.e(url('admin/products.php')).'">Back to products</a>'.($product?'<a class="button" target="_blank" rel="noopener" href="'.e(url('product.php?slug='.rawurlencode((string)$product['slug']))).'">View product ↗</a>':'').'</div>';require __DIR__.'/_header.php';
$keywords='';if($product){$decoded=json_decode((string)($product['keywords']??'[]'),true);$keywords=is_array($decoded)?implode(', ',$decoded):'';}
