</aside></div></form>
<?php elseif($tab==='variants'&&$product): ?><div class="form-grid"><section class="panel"><header class="panel__header"><h2>Variant matrix</h2><span><?= count($product['variants']) ?> variants</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Color</th><th>Size</th><th>SKU</th><th class="numeric">Stock</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($product['variants']as$row): ?><tr><td><span style="display:inline-block;width:.7rem;height:.7rem;background:<?= e((string)$row['color_hex']) ?>;border:1px solid #555;margin-right:.4rem"></span><?= e((string)$row['color_name']) ?></td><td><?= e((string)$row['size']) ?></td><td><strong><?= e((string)$row['sku']) ?></strong></td><td class="numeric <?= (int)$row['stock_quantity']===0?'stock-out':((int)$row['stock_quantity']<=(int)setting('low_stock_threshold','5')?'stock-low':'') ?>"><?= (int)$row['stock_quantity'] ?></td><td><span class="<?= e(admin_status_class((bool)$row['is_active']?'active':'disabled')) ?>"><?= (bool)$row['is_active']?'Active':'Disabled' ?></span></td><td class="actions"><a class="button button--small button--quiet" href="?id=<?= (int)$id ?>&tab=variants&variant=<?= (int)$row['id'] ?>">Edit</a><form method="post" data-confirm="Delete this unreferenced variant?"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$id ?>"><input type="hidden" name="variant_id" value="<?= (int)$row['id'] ?>"><button class="button button--small button--danger" name="action" value="delete_variant">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
