ug</span><input name="color_slug" value="<?= e((string)$image['color_slug']) ?>"></label><label class="check-field"><input type="checkbox" name="is_primary" value="1" <?= $image['is_primary']?'checked':'' ?>> Primary image</label><button class="button button--small" type="submit">Save image</button></form><form method="post" data-confirm="Remove this image? Runtime uploads are deleted from disk."><?= csrf_field() ?><input type="hidden" name="action" value="delete_image"><input type="hidden" name="product_id" value="<?= (int)$id ?>"><input type="hidden" name="image_id" value="<?= (int)$image['id'] ?>"><button class="button button--small button--danger" type="submit">Remove</button></form></article><?php endforeach; ?></div><?php if(!$product['images']): ?><div class="empty-state"><p>No images yet.</p></div><?php endif; ?></section><?php endif; ?>
